-- 154_replace_decision_42_2019_sharia_supervisory_committees_sukuk_consolidated_single_article_with_preamble_nine_articles_and_footnotes.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (42) لسنة 2019 (بتاريخ 2019/3/19) بشأن ضوابط تشكيل واشتراطات عضوية لجان الرقابة الشرعية لإصدارات الصكوك
-- والمنتجات المالية غير المصرفية المتوافقة مع أحكام الشريعة الإسلامية، بالنص الموحد "وفقاً لآخر تعديل بتاريخ 2025/2/12" (تعديل بقرار مجلس إدارة الهيئة رقم 50 لسنة 2025)
-- كما نشرته الهيئة على موقعها.
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة أ) =====
-- مخزَّن بالهجرة 035 كمادة واحدة (article_no = 1، 12528 حرفاً) تحوى القرار كله (العنوان والديباجة والمواد التسع والمادة الثامنة مكرراً والحواشى) بلا ديباجة مستقلة ولا مواد، فلا يمكن
-- الاستشهاد بمادة بعينها (المادة 3 شروط العضوية، المادة 4 الاختصاصات، المادة 8 مكرراً شروط القيد). وبمقابلته بملف الهيئة المقدَّم وُجدت فيه فروق فى النص نفسه لا فى الهيكل فقط:
--   * "وحفظ قيودها وسجلاتها" فى المادة 2 والصواب فى الأصل "وسجلاته" (فرق لفظى)؛
--   * تصحيح إملائى غير مبرر لأخطاء الأصل: "الشريعة الإسلامية" بدل "الاسلامية" (مرتين فى البندين 3 و4 من المادة 4)، و"مجلس إدارة" بدل "مجلس ادارة" (البند 3)،
--     و"الفتاوى" بدل "الفتاوي" (البند 13)، و"مدى" بدل "مدي" (البند (أ))؛
--   * الحواشى مدمجة فى عشرة هوامش مختلفة الصياغة عن الأصل: الهامش (1) فى الأصل جملتان فقط (تعديل القرار بالقرارين 61/2019 و176/2022) بينما أُدمج فيه محتوى الهامشين (2) و(3)
--     (عنوان القرار والمادة الأولى وإضافة الفقرة الثانية بقرار 50/2025) فصار الهامش (2) و(3) مكرَّرين، والهامش (4) "وقرار رقم 50" بدل "، قرار رقم 50 ... باريخ"، وأُضيفت
--     كلمة "الحواشى:" وفاصل "---" ليسا من الأصل؛
--   * تواريخ بصيغة "30/11/2022" بدل صيغة الأصل "2022/11/30"، وترقيم البنود "1." بدل "1-" فى القوائم التى ترقّمها الأصل بالشرطة.
-- (والباقى مطابق كلمة بكلمة: الفرق فى الأصل لا يتجاوز ما سبق.)
--
-- ===== المصدر والمنهجية =====
-- PDF الهيئة الموحد (6 صفحات، مُنتَج بـ Word 2013، قدّمه صاحب المشروع مرتين بالمحتوى نفسه، md5 واحد). طبقته النصية صحيحة الحروف لكن ترتيب بعض الحروف مقلوب فى الوصلات
-- (لا/ال: "جملس" و"املادة" و"االطالع") فلا تصلح نسخاً مباشراً؛ فقوبل النص المخزَّن بها بمفتاح الحروف المرتبة لكل كلمة (يزيل أثر الوصلات المقلوبة ويُبقى الهمزة والياء/الألف المقصورة
-- والتاء المربوطة على حالها)، وقوبل بمخرجات OCR مستقلة (tesseract ara، 250 dpi)، وقُرئت الصفحات الست بصرياً (130 dpi) وكُبِّرت الهوامش (250 dpi). فُرِض نص الأصل
-- على المخزَّن فى الفروق الخمسة اللفظية/الإملائية أعلاه (وكلها فى الطبقة النصية للأصل). الهوامش العشرة نُقلت من الأصل بصرياً (وهى فى الأصل فى أسفل الصفحات 1-5)
-- مع الإبقاء على أخطاء الأصل ("المادة الاولي" و"باريخ" فى الهامشين 3 و4). الأرقام والمراجع مطابقة (القانون 95/1992 ولائحته، 10/2009، قرار رئيس الجمهورية 192/2009،
-- قرار 8/2014، القرارات المعدِّلة 61/2019 فى 2019/4/30، 176/2022 فى 2022/11/30، 50/2025 فى 2025/2/12، ثلاث سنوات، خمس سنوات، ثلاثة آلاف جنيه، ثلاثة أشهر).
-- أُبقى إملاء الأصل (الياء "ي" فى "في" و"الاسلامية" بلا همزة فى موضعين و"ادارة" و"الفتاوي" و"مدي" و"المادة الاولي")، وعلامات الترقيم ملاصقة. حُذفت ترويسة الصفحات وأرقامها
-- وسطر "مجلس إدارة الهيئة العامة للرقابة المالية". الأرقام لاتينية. أُسقطت علامات التشكيل الصغيرة وأُبقى تنوين الفتح. علامات الهوامش فى المتن "(n)" كما فى الهجرة 138،
-- وما كان منها على عناوين المواد (2) و(5) و(6) و(10) نُقل إلى عنوان المادة، وعلامة (1) إلى hierarchical_location للديباجة مع عنوان القرار وعبارة "النص الموحد".
-- المادة 8 مكرراً: article_no = 8 وarticle_suffix_order = 1 (كما فى بقية مواد "مكرراً" فى القاعدة). القسم 10 "هوامش التعديلات اللاحقة" يضم الهوامش العشرة.
--
-- ===== الهيكل =====
-- 12 صفاً، 12 نسخة (version_no = 1): ديباجة (article_no = 0) بخمسة اطلاعات وموافقة المجلس، والمواد 1–8: اللجنة المركزية واختصاصاتها الأربعة (م1)، تشكيلها وأمانتها الفنية (م2)،
-- شروط العضوية (م3)، اختصاصات اللجنة الثلاثة عشر وصلاحياتها (م4)، اجتماعاتها (م5)، اللجان الفرعية (م6)، تعيين أعضائها (م7)، عرض المستندات عليها (م8)، المادة 8 مكرراً شروط القيد
-- فى سجل أعضاء اللجان الفرعية، المادة 9 النشر، ثم القسم 10 الهوامش. المفتاح (1، 0) محفوظ فلا تعيد بذرة 035 إدراج المادة القديمة (إدراج laws فيها ON CONFLICT DO NOTHING،
-- وإدراج المادة مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ والنسخ (قرار تقديرى يُراجَع) =====
-- النص المتاح هو الموحد بعد تعديل 2025/2/12 فقط؛ لا نص أصلى لعام 2019 ولا نصوص المراحل الوسيطة (61/2019 و176/2022)، ولا تواريخ نشر بالوقائع للقرارات الأربعة فى المصدر.
-- فجُعل effective_from = 2025-02-12 (تاريخ آخر تعديل المذكور فى المصدر) للنسخ الاثنتى عشرة، وسُجِّل amended_by = 50/2025 مع change_note على المادتين 1 و2 (اللتين مسّهما
-- تعديل 2025). أما تعديلات 2019 و2022 على بقية المواد فتفصّلها الهوامش فى القسم 10 دون إنشاء نسخ لها. أثر ذلك: لا نسخة للقرار قبل 2025-02-12 فى الاستعلام بالتاريخ (فجوة معلنة
-- بدل نص معدَّل منسوب لتواريخ سابقة)، كما فعلت الهجرة 138. لاحقاً: رفع نصوص 2019 الأصلية والتعديلات 61/2019 و176/2022 و50/2025 لبناء النسخ التاريخية.
-- لا تُمس بيانات laws (enacted_at = 2019-03-19 وlast_amended_at = 2025-02-12 قائمان).
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (12 صفاً بديباجة سليمة والقسم 10 موجود)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف
-- (عدد، لفظ مغاير للأصل أو تواريخ بصيغة مغايرة أو فاصل حواشى قديم، محتوى المواد، إجمالى الطول 11688 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.

BEGIN;
DO $fix154$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[154] القرار 42/2019 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 12
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[154] القرار 42/2019 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[154] أُزيلت % مادة من القرار 42/2019 (القرار كله فى مادة واحدة والمتن به فروق عن نص الهيئة وهوامش مدمجة)', v_n;
  END IF;
END
$fix154$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (42) لسنة 2019 بتاريخ 2019/3/19 بشأن ضوابط تشكيل واشتراطات عضوية لجان الرقابة الشرعية لإصدارات الصكوك والمنتجات المالية غير المصرفية المتوافقة مع أحكام الشريعة الإسلامية (النص الموحد وفقاً لآخر تعديل بتاريخ 2025/2/12) (1)$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 ولائحته التنفيذية؛
وعلى القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية؛
وعلى قرار رئيس الجمهورية رقم (192) لسنة 2009 بإصدار النظام الأساسي للهيئة العامة للرقابة المالية؛
وعلى قرار مجلس إدارة الهيئة رقم (8) لسنة 2014 بشأن تنظيم عمل لجان الرقابة الشرعية للمنتجات المالية الصادرة وفقاً لأحكام الشريعة الإسلامية؛
وعلى خطاب الأزهر الشريف بشأن الموافقة على ضوابط تشكيل واشتراطات عضوية لجان الرقابة الشرعية لإصدارات الصكوك المتوافقة مع أحكام الشريعة الإسلامية؛
وعلى موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2019/3/19.
قرر$b0_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-02-12', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى (2)$t1_0$, $b1_0$تشكل لجنة مركزية للرقابة الشرعية تتولى القيام بما يلي:
1- اعتماد إصدار الصكوك المتوافقة مع أحكام الشريعة الإسلامية المقدمة من الجهات المصدرة لها وتشرف من الناحية الشرعية على إصدارات هذه الصكوك واستخدام حصيلتها، كما تقوم بمراجعة التقارير ربع السنوية التي تقدم للهيئة من قبل لجان الرقابة الشرعية الفرعية بالمؤسسات العاملة في الأنشطة المالية غير المصرفية التي تجيز إصدار الصكوك التي تتوافق مع أحكام الشريعة الإسلامية خلال الفترة من إصدار الصكوك وحتى الاسترداد وفقاً لقواعد ومعايير الإفصاح الصادرة عن الهيئة.
2- اعتماد إصدار المنتجات المالية غير المصرفية المتوافقة مع أحكام الشريعة الإسلامية.
3- اعتماد قيد لجان الرقابة الشرعية الفرعية في السجل المخصص لذلك لكافة الأنشطة المالية غير المصرفية.
4- تنمية وتطوير أدوات ومنتجات الأنشطة المالية غير المصرفية المتوافقة مع أحكام الشريعة الإسلامية.
ويكون للجنة إبداء أي إيضاحات أو ملاحظات على أي من بنود الإصدار أو بعضها إذا ارتأت أنها غير متوافقة مع أحكام الشريعة الإسلامية، وتلتزم الشركة أو الجهة بالإفصاح عن تلك الإيضاحات أو الملاحظات. (3)$b1_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, amended_by_law_no, amended_by_law_year, change_note)
SELECT id, 1, body, '2025-02-12', 'active', 50, 2025, $c1_0$النص الموحد: استبدال المادة الأولى بقرار 176/2022 وإضافة الفقرة الثانية بقرار مجلس إدارة الهيئة رقم 50 لسنة 2025 بتاريخ 2025/2/12$c1_0$ FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية$t2_0$, $b2_0$تشكل اللجنة المشار إليها بالمادة الأولى من هذا القرار من سبعة أعضاء تكون غالبيتهم من أبرز علماء الشريعة الإسلامية والمتخصصين الذين لديهم خبرة واسعة في المجالات الاقتصادية والمحاسبية والأنشطة المالية المصرفية وغير المصرفية المرتبطة بمجالات التمويل الإسلامي. (4)
ويصدر بتشكيل اللجنة قرار من مجلس إدارة الهيئة لمدة ثلاث سنوات قابلة للتجديد بعد موافقته على ذلك.
ويكون للجنة أمانة فنية من موظفي الهيئة الذين يحددهم رئيس الهيئة، ويكون رئيسها أميناً عاماً للجنة، وتتولى الأمانة الفنية للجنة تدوين محاضر جلساتها ومتابعة تنفيذ قراراتها وحفظ قيودها وسجلاته، والتنسيق بين الإدارات المختلفة بالهيئة وطلب البيانات والأبحاث في الموضوعات المرتبطة بعمل لجنة الرقابة الشرعية المركزية وفقاً للقواعد والإجراءات التي يعتمدها رئيس الهيئة، وكذا التنسيق والاتصال مع المؤسسات ولجان الرقابة الشرعية بالدول الإسلامية في ضوء المهام التي يحددها رئيس لجنة الرقابة الشرعية المركزية.
ولمجلس إدارة الهيئة إعادة تشكيل اللجنة وله إعفاء بعض أعضائها وذلك بقرار مسبب بعد توجيه إنذار مشفوع بالمبررات وتحديد مدة للتصحيح، وبعد الاستماع إلى وجهات نظر هيئة الرقابة الشرعية أو أعضائها المقرر إعفائهم.$b2_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, amended_by_law_no, amended_by_law_year, change_note)
SELECT id, 1, body, '2025-02-12', 'active', 50, 2025, $c2_0$النص الموحد: استبدال الفقرة الثالثة من المادة الثانية بقرار 176/2022 ثم بقرار مجلس إدارة الهيئة رقم 50 لسنة 2025 بتاريخ 2025/2/12$c2_0$ FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة (5)$t3_0$, $b3_0$يجب أن يتوافر في أعضاء لجنة الرقابة الشرعية المركزية الشروط الآتية:
1- أن يتم قيد أعضاء اللجنة في سجل خاص يعد لهذا الغرض لدى الهيئة للأعضاء الذين يوافق مجلس إدارة الهيئة على انضمامهم للجنة.
2- ألا يكون مساهماً رئيسياً أو عضو مجلس إدارة في أي من الشركات التي تزاول أنشطة مالية غير مصرفية، خلال السنتين السابقتين على العضوية.
وعلى مجلس إدارة الشركات المشار إليها ورئيس لجنة الرقابة الشرعية المركزية موافاة الهيئة بأي حالات تعارض في المصالح ممكنة أو محتملة.
وإذا كان عضو لجنة الرقابة الشرعية المركزية عضواً بإحدى لجان الرقابة الشرعية الفرعية، يتم استبعاد تصويته على القرارات حال عرض موضوعات تخص اللجنة الفرعية التي يكون عضواً بها.$b3_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-02-12', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة (6)$t4_0$, $b4_0$تختص لجنة الرقابة الشرعية المركزية بما يلي:
1- الاشتراك مع الهيئة في وضع نماذج العقود والاتفاقيات الخاصة بإصدار الصكوك والأدوات والعقود والمنتجات المالية غير المصرفية التي تتوافق مع أحكام الشريعة الإسلامية للتأكد من خلوها من المحظورات الشرعية.
2- وضع المعايير والأطر والأحكام العامة للجانب الشرعي في إصدارات الصكوك والأدوات والعقود والمنتجات المالية غير المصرفية التي تتوافق مع أحكام الشريعة الإسلامية.
3- إبداء الرأي والتصنيف الشرعي لطلبات إصدارات الصكوك وفقاً لأحكام الشريعة الاسلامية بحسب توافقها، إظهاراً لحجم المخاطر لمراعاة حقوق حاملي الصكوك وعرضها على مجلس ادارة الهيئة، مع تقديم مقترحات عملية للجهة المصدرة لتصحيحها أو تغيير التصنيف إن أمكن، وكذا إبداء الرأي والتصنيف الشرعي في الطلبات والتقارير التي تقدم إليها دورياً من الهيئة أو لجان الرقابة الشرعية الفرعية.
4- إبداء الرأي والمشورة فيما يعهد إليها من التقارير التي تقدم اليها دورياً من لجنة الرقابة الشرعية الفرعية بالمؤسسات العاملة في الأنشطة المالية غير المصرفية للتحقق من استمرار التعامل في صكوك المصدرة وفقاً لأحكام الشريعة الإسلامية من تاريخ الإصدار وحتى الاسترداد وفقاً لمبادئ الشريعة الاسلامية وأحكامها وطبقاً لمعايير وقواعد الإفصاح الصادرة عن الهيئة في هذا الشأن.
5- دراسة المشاكل الشرعية التي تواجه إصدارات الصكوك خلال عمر الصك وكذا المنتجات المالية غير المصرفية (إن وجدت) وإبداء الرأي فيها واقتراح الحلول لها.
6- مراجعة استفسارات لجان الرقابة الشرعية الفرعية بالمؤسسات العاملة في الأنشطة المالية غير المصرفية وإصدار الفتاوى الشرعية في أحكام قيد وتداول أو استرداد أي من إصدارات الصكوك أو فيما يتعلق بالمنتجات المالية غير المصرفية أو غيرها من الموضوعات التي يطلب في شأنها فتوى شرعية.
7- مساعدة الهيئة في وضع برامج تدريب أعضاء لجان الرقابة الشرعية الفرعية بالمؤسسات المالية غير المصرفية أو العاملين المختصين بما يؤدى إلى استيعاب الصيغ الإسلامية والجوانب الفقهية والشرعية في إصدارات الصكوك أو المنتجات المالية غير المصرفية التي تتوافق مع أحكام الشريعة الإسلامية.
8- وضع ضوابط عمل وحوكمة اللجان الشرعية الفرعية.
9- إنشاء قاعدة بيانات عن الأنشطة المالية غير المصرفية التي تتوافق مع أحكام الشريعة الإسلامية بمصر والدول الإسلامية، وحصر الفتاوى والمراجع المرتبطة بها.
10- اتخاذ ما يلزم للتنسيق مع لجان الرقابة الشرعية المركزية بالدول الإسلامية.
11- تقديم تقرير سنوي لمجلس إدارة الهيئة عن السلامة الشرعية لإصدارات الصكوك والمنتجات المالية غير المصرفية القائمة بالسوق بناءً على دراسة مستوفية لذلك الغرض ووفقاً للتقارير الدورية المقدمة إليها من قبل لجان الرقابة الشرعية الفرعية المعتمدة لتلك الإصدارات، كما يجب أن يتضمن التقرير ما قامت به اللجنة لتنشيط وتطوير المنتجات المالية غير المصرفية التي تتوافق مع أحكام الشريعة الإسلامية.
12- إصدار لائحة لتنظيم أعمالها وتحديد اجتماعاتها.
13- النظر والبت في المنازعات المحالة إليها التي تنشأ بين المؤسسات العاملة في الأنشطة المالية غير المصرفية ولجان الرقابة الشرعية الفرعية عن أي من الفتاوي أو الجوانب الفقهية وذلك للنظر في التفسيرات الخاصة بالمقررات الشرعية.
كما تختص اللجنة بأي أمور أخرى تتفق مع أغراضها وفقاً لما يسنده إليها رئيس الهيئة.
ويكون للجنة في سبيل تحقيق الاختصاصات المنصوص عليها في هذا القرار ما يلي:
(أ) الاطلاع على أي مستندات أو وثائق أو سجلات أو عقود أو مكاتبات ترى أنها لازمة وضرورية لتمكينها من أداء مهامها للتوصل إلى مدي التزام اللجان الشرعية الفرعية مع الأحكام الشرعية.
(ب) إجراء تفتيش على أعمال لجان الرقابة الشرعية الفرعية بالمؤسسات المالية غير المصرفية التي يوكل إليها مهام إبداء الرأي في إصدارات الصكوك أو المنتجات المالية غير المصرفية بغرض التأكد من سلامة تطبيق الجوانب الشرعية في أعمالها.
(ج) تلتزم لجان الرقابة الشرعية الفرعية بإمداد الأمانة الفنية للجنة الرقابة الشرعية المركزية بأي تقارير أو فتاوى صدرت منهم للمؤسسات العاملة في الأنشطة المالية غير المصرفية خلال ثلاثة أشهر على الأكثر من إصدارها.
وعلى الأمانة الفنية للجنة الرقابة الشرعية حصر وجمع الفتاوى التي تخص الأنشطة المالية غير المصرفية المتوافقة مع أحكام الشريعة الإسلامية من المنظمات والمؤسسات الإسلامية.
وللجنة أن تستعين في ذلك بمن تراه ضرورياً من العاملين بالهيئة، وذلك بعد موافقة رئيس الهيئة أو من يفوضه في ذلك.$b4_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-02-12', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة$t5_0$, $b5_0$تعقد لجنة الرقابة الشرعية المركزية اجتماعها الأول بدعوة من رئيس الهيئة أو من يفوضه في ذلك، وتنتخب اللجنة في هذا الاجتماع من بين أعضائها رئيساً لها ونائباً للرئيس.
وتجتمع اللجنة بدعوة من رئيسها أو نائبه عند غيابه مرة على الأقل كل شهر ويكون اجتماعها صحيحاً بحضور أغلبية أعضائها على أن يكون من بينهم الرئيس أو نائبه، وتتخذ قراراتها بأغلبية أعضائها وفي حالة التساوي يرجح الجانب الذي منه الرئيس. (7)$b5_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
