WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, $t8_0$المادة الثامنة$t8_0$, $b8_0$تعرض على لجنة الرقابة الشرعية الفرعية للمؤسسات العاملة في الأنشطة المالية غير المصرفية، المستندات أو المذكرات أو نشرات الاكتتاب أو مذكرات المعلومات أو العقود أو الأدوات المالية الاستثمارية التي يطلق عليها متوافقة مع أحكام الشريعة الإسلامية أو غيرها من المستندات اللازمة لممارسة نشاطها، للاطلاع والدراسة الكاملة من كافة الجوانب الشرعية في ضوء فتاوى لجنة الرقابة الشرعية المركزية ومقرراته، ويكون للجنة إما إقرار ما هو معروض عليها كما هو بعد التأكد من الالتزام بالمعايير الشرعية أو بعد إدخال بعض التعديلات الضرورية أو رده أحياناً في حالة تعذر الإقرار أو التعديل، ويصدر قرار بأغلبية أعضائها. (9)
وتسجل فتاوى وقرارات اللجنة في سجلات خاصة بذلك، وتحفظ لمدة لا تقل عن خمس سنوات.$b8_0$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
