WITH ins8_1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 1, NULL, $t8_1$المادة الثامنة مكرراً (10)$t8_1$, $b8_1$يشترط فيمن يتقدم للقيد في سجل أعضاء لجان الرقابة الشرعية الفرعية بالهيئة، ما يلي:
1- أن يكون حاصلاً على درجة العالمية (الدكتوراه) من جامعة الأزهر أو ما يعادلها في أحد التخصصات ذات العلاقة.
2- أن يكون له دراستين علميتين متخصصتين على الأقل منشورتين في دورية علمية في مجالات المعاملات المالية أو المحاسبية أو الاقتصادية المتوافقة مع الشريعة الإسلامية.
3- ألا يكون قد سبق الحكم عليه بعقوبة جناية أو جنحة في جريمة ماسة بالشرف أو الأمانة أو إحدى الجرائم المنصوص عليها في قوانين الشركات أو التجارة أو أحد القوانين الواردة بالمادة الثالثة من قانون تنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية المشار إليه، ما لم يكن قد رد إليه اعتباره.
ويجوز الاستثناء من البندين الأول والثاني من شروط القيد الواردة بهذه المادة إذا توافرت إحدى الشروط التالية فيمن يتقدم للقيد:
1. أن يكون قد شغل منصب مفتي جمهورية مصر العربية.
2. أن يأتي ترشيحه من فضيلة الإمام الأكبر شيخ الأزهر الشريف أو مفتي جمهورية مصر العربية.
3. أن يقدم ما يفيد أنه قد سبق له عضوية لجان رقابة شرعية مماثلة في بنوك أو مؤسسات مالية أو صناديق استثمار لمدة ثلاث سنوات سابقة.
ويكون القيد في سجل الهيئة المشار إليه لمدة ثلاث سنوات، تجدد بناءً على طلب كتابي من المتقدم وبشرط استيفاء متطلبات استمرار القيد التي تحددها الهيئة.
ويكون مقابل خدمات القيد أو تجديده مبلغ ثلاثة آلاف جنيه، تسدد مع تجديد الطلب.$b8_1$
  FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-02-12', 'active' FROM ins8_1;

