DO $verify154$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 42 AND law_year = 2019 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[154] القرار 42/2019 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 12 THEN RAISE EXCEPTION '[154] عدد المواد % بدل 12', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2025-02-12';
  IF v_v <> 12 THEN RAISE EXCEPTION '[154] عدد النسخ % بدل 12', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%وسجلاتها%' OR body LIKE '%الشريعة الإسلامية بحسب توافقها%' OR body LIKE '%عن أي من الفتاوى أو الجوانب%' OR body LIKE '%مدى التزام%' OR body LIKE '%الحواشي%' OR body LIKE '%---%' OR body LIKE '%30/11/2022%' OR body LIKE '%12/2/2025%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[154] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع%' AND body LIKE '%رقم (95) لسنة 1992%' AND body LIKE '%رقم (192) لسنة 2009%' AND body LIKE '%رقم (8) لسنة 2014%' AND body LIKE '%خطاب الأزهر الشريف%' AND body LIKE '%بتاريخ 2019/3/19.%' AND body LIKE '%قرر') THEN RAISE EXCEPTION '[154] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تشكل لجنة مركزية للرقابة الشرعية%' AND body LIKE '%4- تنمية وتطوير أدوات%' AND body LIKE '%الملاحظات. (3)') THEN RAISE EXCEPTION '[154] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'تشكل اللجنة المشار إليها%' AND body LIKE '%الإسلامي. (4)%' AND body LIKE '%وسجلاته،%' AND body LIKE '%المقرر إعفائهم.') THEN RAISE EXCEPTION '[154] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'يجب أن يتوافر في أعضاء لجنة%' AND body LIKE '%2- ألا يكون مساهماً رئيسياً%' AND body LIKE '%عضواً بها.') THEN RAISE EXCEPTION '[154] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'تختص لجنة الرقابة الشرعية المركزية بما يلي:%' AND body LIKE '%الشريعة الاسلامية بحسب توافقها%' AND body LIKE '%مجلس ادارة الهيئة، مع تقديم%' AND body LIKE '%10- اتخاذ ما يلزم%' AND body LIKE '%13- النظر والبت%الفتاوي%' AND body LIKE '%مدي التزام%' AND body LIKE '%(ج) تلتزم لجان%' AND body LIKE '%من يفوضه في ذلك.') THEN RAISE EXCEPTION '[154] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تعقد لجنة الرقابة الشرعية المركزية اجتماعها الأول%' AND body LIKE '%الجانب الذي منه الرئيس. (7)') THEN RAISE EXCEPTION '[154] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'تشكل لجان فرعية للرقابة الشرعية%' AND body LIKE '%رقم (8) لسنة 2014%') THEN RAISE EXCEPTION '[154] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'يعين أعضاء لجنة الرقابة الشرعية الفرعية%' AND body LIKE '%بذلك. (8)%' AND body LIKE '%كل شهر.') THEN RAISE EXCEPTION '[154] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'تعرض على لجنة الرقابة الشرعية الفرعية%' AND body LIKE '%أعضائها. (9)%' AND body LIKE '%خمس سنوات.') THEN RAISE EXCEPTION '[154] المادة 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 1 AND body LIKE 'يشترط فيمن يتقدم للقيد%' AND body LIKE '%3- ألا يكون قد سبق الحكم%' AND body LIKE '%1. أن يكون قد شغل منصب مفتي%' AND body LIKE '%ثلاثة آلاف جنيه%') THEN RAISE EXCEPTION '[154] المادة 8 مكرراً غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية%' AND body LIKE '%بالوقائع المصرية.') THEN RAISE EXCEPTION '[154] المادة 9 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE '(1) تم تعديل القرار بموجب%' AND body LIKE '%(4)%باريخ 2025/2/12.%' AND body LIKE '%(10) تم إضافة المادة الثامنة مكرر%') THEN RAISE EXCEPTION '[154] الهوامش غير سليم'; END IF;
  IF v_len <> 11688 THEN RAISE EXCEPTION '[154] إجمالى طول المواد % بدل 11688', v_len; END IF;
  RAISE NOTICE '[154] القرار 42/2019: 12 مواد و12 نسخ، إجمالى % حرف', v_len;
